@startuml

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + firstName : string
  + lastName : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + name : string
  + weight : float
}

class Material {
  + name : string
}

class Client {
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : string
  + dateMade : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
}

Machine "*" -- "*" Worker : is operated by
ProductType "*" -- "1" Machine : is produced in
ProductType "*" -- "1" Material : is produced from
Client "1" -- "*" PurchaseOrder : issues
PurchaseOrder "1" -- "1..*" OrderLine : contains
OrderLine "*" -- "1" ProductType : refers to

@enduml

